import { GroundEnemy } from './GroundEnemy';
export class Wight extends GroundEnemy {
    constructor(props) {
        super(props, 'wight');
        this.displayName = 'Wight';
        this.windupLabel = 'SHIELD OPEN';
        this.hint = 'The raised shield blocks front shots. Attack from behind or while it opens to bash.';
    }
    get shieldRaised() { return this.state === 'idle' || this.state === 'attack'; }
    blocksShot(shotVX) { return this.shieldRaised && shotVX * this.facing < 0; }
    updateAttack() { this.rush(); }
}
