export class GameElement {
    constructor({ width = 64, height = 64 } = {}) {
        this.x = 0;
        this.y = 0;
        this.width = width;
        this.height = height;
    }
    get x2() { return this.x + this.width; }
    get y2() { return this.y + this.height; }
    spawn({ x, y }) {
        this.x = x;
        this.y = y;
    }
}
