export class SignRenderer {
    constructor(ctx) {
        this.ctx = ctx;
    }
    draw(sign) {
        const c = this.ctx;
        c.textAlign = 'left';
        c.font = 'bold 12px monospace';
        c.fillStyle = '#9fae99';
        c.fillText(sign.title, sign.x, sign.y);
        c.font = '10px monospace';
        c.fillStyle = '#637f78';
        c.fillText(sign.text, sign.x, sign.y + 18);
    }
}
