export class ProjectileRenderer {
    constructor(ctx) {
        this.ctx = ctx;
    }
    draw(projectiles) {
        const c = this.ctx;
        for (const shot of projectiles) {
            c.shadowColor = shot.glowColor;
            c.shadowBlur = 14;
            c.fillStyle = shot.color;
            c.fillRect(shot.x, shot.y, shot.width, shot.height);
            c.fillStyle = shot.coreColor;
            c.fillRect(shot.x + 4, shot.y + 2, 5, 4);
        }
        c.shadowBlur = 0;
    }
}
