import { GroundEnemy } from './GroundEnemy';
export class Ghoul extends GroundEnemy {
    constructor(props) {
        super(props, 'ghoul');
        this.displayName = 'Ghoul';
        this.windupLabel = 'LEAP';
        this.hint = 'The crouch warns of a leap. It cannot turn once launched.';
    }
    get spriteAnchorY() { return .87; }
    canBeginAttack() { return this.grounded; }
    beginAttack() { this.vy = -350; this.grounded = false; }
    updateAttack() { this.rush(); }
}
