import { GroundEnemy } from './GroundEnemy';
export class Skeleton extends GroundEnemy {
    constructor(props) {
        super(props, 'skeleton');
        this.displayName = 'Skeleton';
        this.windupLabel = 'CHARGING';
        this.hint = 'The emitter locks a firing lane. Jump the cyan bolt.';
    }
    get tracksPlayer() { return false; }
    beginAttack() { this.fireDirection(this.facing, 0); }
    get aimLine() {
        if (this.state !== 'windup')
            return undefined;
        return { x: this.x + this.width / 2, y: this.y + 26,
            endX: this.x + this.width / 2 + this.facing * 230, endY: this.y + 26 };
    }
}
