import { GameElement } from './GameElement';
import { moveBody } from '../game/physics';
import { tuning } from '../game/config';
export class Actor extends GameElement {
    constructor() {
        super(...arguments);
        this.vx = 0;
        this.vy = 0;
        this.grounded = false;
    }
    applyGravity(dt) {
        this.vy = Math.min(tuning.maxFall, this.vy + tuning.gravity * dt);
    }
    move(dt, solids) {
        moveBody(this, solids, dt);
    }
}
