import { createActionLevel } from '../maps/actionLevel';
import { Character } from '../components/Character';
import { Map } from '../components/Map';
import { Camera } from '../components/Camera';
import { createEnemy } from './EnemyFactory';
import { CollisionSystem } from './CollisionSystem';
import { ParticleSystem } from './ParticleSystem';
import { Graveyard } from './Graveyard';
import { Combat } from './Combat';
export class World {
    constructor(level = createActionLevel()) {
        this.camera = new Camera();
        this.effects = new ParticleSystem();
        this.projectiles = [];
        this.events = [];
        this.state = 'playing';
        this.elapsed = 0;
        this.level = new Map(level);
        this.collisions = new CollisionSystem(this.level);
        this.graveyard = new Graveyard(this);
        this.combat = new Combat(this);
        this.player = new Character({ gameArea: this });
        this.enemies = this.level.enemies.map((spawn, id) => createEnemy({ gameArea: this, spawn, id }));
        this.camera.follow(this.player, this.level);
    }
    get defeated() { return this.combat.defeated; }
    get corpses() { return this.graveyard.corpses; }
    get particles() { return this.effects.particles; }
    update(dt, input) {
        this.events = [];
        if (this.state !== 'playing')
            return;
        this.elapsed += dt;
        this.player.update(dt, input);
        this.graveyard.update(dt);
        for (const enemy of [...this.enemies]) {
            if (enemy.health <= 0)
                continue;
            const previous = enemy.state;
            enemy.update(dt);
            if (enemy.state === 'windup' && previous !== 'windup')
                this.events.push('charge');
            if (enemy.y > this.level.height + 100)
                this.combat.defeatEnemy(enemy);
        }
        this.projectiles = this.projectiles.filter(shot => shot.update(this, dt));
        this.enemies = this.enemies.filter(enemy => enemy.health > 0);
        this.combat.checkContacts();
        if (this.player.health <= 0 || this.player.y > this.level.height + 100)
            this.state = 'dead';
        if (this.state === 'playing' && this.level.exit.reachedBy(this.player)) {
            this.state = 'won';
            this.events.push('win');
        }
        this.effects.update(dt);
        this.camera.follow(this.player, this.level);
    }
}
