export class Input {
    constructor(canvas, action, blurTarget = window) {
        this.canvas = canvas;
        this.action = action;
        this.blurTarget = blurTarget;
        this.held = new Set();
        this.jump = false;
        this.keys = new Set(['KeyA', 'KeyD', 'KeyW', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Space', 'KeyJ', 'KeyX', 'KeyP', 'Escape', 'KeyR', 'KeyM', 'F2']);
        this.clear = () => { this.held.clear(); this.jump = false; };
        this.keyDown = (event) => {
            if (!this.keys.has(event.code))
                return;
            event.preventDefault();
            if (!this.held.has(event.code) && !event.repeat) {
                if (['KeyW', 'ArrowUp', 'Space'].includes(event.code))
                    this.jump = true;
                if (['KeyP', 'Escape', 'KeyR', 'KeyM', 'F2'].includes(event.code))
                    this.action(event.code);
            }
            this.held.add(event.code);
        };
        this.keyUp = (event) => {
            if (this.keys.has(event.code))
                event.preventDefault();
            this.held.delete(event.code);
        };
        canvas.addEventListener('keydown', this.keyDown);
        canvas.addEventListener('keyup', this.keyUp);
        canvas.addEventListener('blur', this.clear);
        this.blurTarget.addEventListener('blur', this.clear);
    }
    sample() {
        const controls = { left: this.held.has('KeyA') || this.held.has('ArrowLeft'),
            right: this.held.has('KeyD') || this.held.has('ArrowRight'),
            fire: this.held.has('KeyJ') || this.held.has('KeyX'), jump: this.jump };
        this.jump = false;
        return controls;
    }
    dispose() {
        this.clear();
        this.canvas.removeEventListener('keydown', this.keyDown);
        this.canvas.removeEventListener('keyup', this.keyUp);
        this.canvas.removeEventListener('blur', this.clear);
        this.blurTarget.removeEventListener('blur', this.clear);
    }
}
