import { overlaps } from './physics';
export class Combat {
    constructor(gameArea) {
        this.gameArea = gameArea;
        this.defeated = 0;
    }
    hurtPlayer() {
        const player = this.gameArea.player;
        if (!player.takeHit())
            return;
        this.gameArea.events.push('hurt');
        this.gameArea.effects.burst(player.x + 16, player.y + 25, '#ff7e88');
    }
    hitEnemy(enemy, shotVX) {
        const result = enemy.receiveHit(shotVX);
        if (result === 'ignored')
            return;
        if (result === 'blocked') {
            this.gameArea.events.push('block');
            this.gameArea.effects.burst(enemy.x + enemy.width / 2 + enemy.facing * 18, enemy.y + 24, '#90e9ed', 5);
            return;
        }
        this.gameArea.events.push('hit');
        if (enemy.health <= 0)
            this.defeatEnemy(enemy);
    }
    defeatEnemy(enemy) {
        enemy.defeat();
        if (!enemy.counted) {
            this.defeated++;
            enemy.counted = true;
        }
        this.gameArea.events.push('defeat');
        this.gameArea.effects.burst(enemy.x + enemy.width / 2, enemy.y + 20, '#d7e1ce', 18);
        this.gameArea.graveyard.add(enemy);
    }
    checkContacts() {
        if (this.gameArea.enemies.some(enemy => enemy.grace <= 0 && enemy.vulnerable && overlaps(this.gameArea.player, enemy)))
            this.hurtPlayer();
    }
}
