export class Corpse {
    constructor(enemy, levelHeight) {
        this.enemy = enemy;
        this.age = 0;
        this.revivable = enemy.revivable && enemy.y < levelHeight;
    }
    update(dt) { this.age += dt; }
    release(claimantId) { if (this.claimedBy === claimantId)
        this.claimedBy = undefined; }
    canReactivate(claimantId) {
        return this.revivable && this.enemy.revives < 1 && this.claimedBy === claimantId;
    }
}
