import { FixedClock } from './FixedClock';
import { tuning } from './config';
const browserScheduler = {
    request: callback => requestAnimationFrame(callback),
    cancel: id => cancelAnimationFrame(id),
    now: () => performance.now(),
};
export class GameLoop {
    constructor(update, draw, scheduler = browserScheduler) {
        this.update = update;
        this.draw = draw;
        this.scheduler = scheduler;
        this.clock = new FixedClock();
        this.lastTime = 0;
        this.active = false;
        this.running = false;
        this.frame = (time) => {
            if (!this.running)
                return;
            const elapsed = Math.max(0, (time - this.lastTime) / 1000);
            const simulated = this.active;
            if (simulated)
                this.clock.advance(elapsed, dt => { if (this.active)
                    this.update(dt); }, tuning.step, tuning.maxCatchUp);
            this.lastTime = time;
            this.draw(elapsed, simulated);
            if (this.running)
                this.frameId = this.scheduler.request(this.frame);
        };
    }
    start() {
        if (this.running)
            return;
        this.running = true;
        this.frameId = this.scheduler.request(this.frame);
    }
    resume() {
        this.clock.reset();
        this.lastTime = this.scheduler.now();
        this.active = true;
    }
    pause() { this.active = false; this.clock.reset(); }
    stop() {
        this.pause();
        this.running = false;
        if (this.frameId !== undefined)
            this.scheduler.cancel(this.frameId);
        this.frameId = undefined;
    }
}
