export class DebugRenderer {
    constructor(ctx) {
        this.ctx = ctx;
    }
    bounds(world) {
        const outline = (bounds, color) => { this.ctx.strokeStyle = color; this.ctx.strokeRect(bounds.x, bounds.y, bounds.width, bounds.height); };
        world.level.solids.forEach(wall => outline(wall, '#5c9b8b'));
        outline(world.player, '#e9f279');
        world.enemies.forEach(enemy => outline(enemy, '#ff7e88'));
        world.projectiles.forEach(shot => outline(shot, '#ffffff'));
    }
    overlay(world) {
        const c = this.ctx, player = world.player;
        c.fillStyle = '#081219';
        c.fillRect(12, 12, 360, 52);
        c.fillStyle = '#ddf3d8';
        c.font = '13px monospace';
        c.textAlign = 'left';
        c.fillText(`x ${player.x.toFixed(0)} y ${player.y.toFixed(0)} vx ${player.vx.toFixed(0)} vy ${player.vy.toFixed(0)}`, 22, 33);
        c.fillText(`${player.grounded ? 'grounded' : 'airborne'} · shots ${world.projectiles.length} · F2 hide`, 22, 53);
    }
}
